/**
 * modules/school/mgmt-routes.js — Management + Facilities & Services route
 * declarations (thin layer).
 *
 * Mounted INSIDE the school router (routes.js → mgmt.js → here) so the
 * audit-trail middleware in routes.js covers every write here too.
 *
 * Most endpoints under /api/school/mgmt are generated by the CRUD factory in
 * mgmt.js keyed by RESOURCES:
 *   GET    /:resource          list (whitelisted ?field= filters)
 *   POST   /:resource          create
 *   PUT    /:resource/:id      update
 *   DELETE /:resource/:id      delete
 * Custom routes (dashboards, attendance register, fee collection, promote,
 * due slips, carry-forward) are registered BEFORE the generic ones.
 */

import { Router } from "express";
import multerLib from "multer";
import { authenticateToken, requireRole } from "../auth/index.js";
import { SCHOOL_ROLES, MGMT_ROLES, INSTRUCTOR_WRITABLE } from "./mgmt-rules.js";
import * as core from "./mgmt-service.js";
import * as students from "./mgmt-service-students.js";
import * as academics from "./mgmt-service-academics.js";
import * as operations from "./mgmt-service-operations.js";
import * as records from "./mgmt-service-records.js";

const router = Router();

const schoolAdminOnly = requireRole(SCHOOL_ROLES);

export function requireMgmtWrite(req, res, next) {
  const role = req.user?.role;
  if (["school", "school_admin", "admin"].includes(role)) return next();
  if (role === "instructor" && INSTRUCTOR_WRITABLE.has(req.params.resource)) return next();
  return res.status(403).json({ error: "Not permitted for this resource" });
}

/* ── Upload middleware ────────────────────────────────────────────────────── */
const studentDocUpload = multerLib({ storage: multerLib.memoryStorage(), limits: { fileSize: 15 * 1024 * 1024 } }).array("files", 20);
const tplFileUpload = multerLib({ storage: multerLib.memoryStorage(), limits: { fileSize: 20 * 1024 * 1024 } }).single("file");
const bulkUpload = multerLib({ storage: multerLib.memoryStorage(), limits: { fileSize: 15 * 1024 * 1024 } }).array("files", 200);
const zipUpload = multerLib({ storage: multerLib.memoryStorage(), limits: { fileSize: 100 * 1024 * 1024 } }).single("file");
const mediaUpload = multerLib({ storage: multerLib.memoryStorage(), limits: { fileSize: 25 * 1024 * 1024 } }).array("files", 20);
const materialUpload = multerLib({ storage: multerLib.memoryStorage(), limits: { fileSize: 25 * 1024 * 1024 } }).single("file");

const uploaded = (upload, handler) => (req, res) => {
  upload(req, res, (uploadErr) => {
    if (uploadErr) return res.status(400).json({ error: uploadErr.message });
    return handler(req, res);
  });
};

